func (o *RunArtifact) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "LeaseRunLease":
		rel, ok := retrieved.(*RunLease)
		if !ok {
			return fmt.Errorf("runArtifact cannot load %T as %q", retrieved, name)
		}

		o.R.LeaseRunLease = rel
		o.R.Loaded.LeaseRunLease = true

		return nil
	case "RunTaskRun":
		rel, ok := retrieved.(*TaskRun)
		if !ok {
			return fmt.Errorf("runArtifact cannot load %T as %q", retrieved, name)
		}

		o.R.RunTaskRun = rel
		o.R.Loaded.RunTaskRun = true

		return nil
	default:
		return fmt.Errorf("runArtifact has no relationship %q", name)
	}
}

