// LoadLeaseRunLease loads the runArtifact's LeaseRunLease into the .R struct
func (o *RunArtifact) LoadLeaseRunLease(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.LeaseRunLease = nil
	o.R.Loaded.LeaseRunLease = false

	related, err := o.LeaseRunLease(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	o.R.LeaseRunLease = related
	o.R.Loaded.LeaseRunLease = true
	return nil
}

// LoadLeaseRunLease loads the runArtifact's LeaseRunLease into the .R struct
func (os RunArtifactSlice) LoadLeaseRunLease(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	runLeases, err := os.LeaseRunLease(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.LeaseRunLease = nil
		o.R.Loaded.LeaseRunLease = true
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range runLeases {

			if !(o.LeaseID == rel.ID) {
				continue
			}

			o.R.LeaseRunLease = rel
			break
		}
	}

	return nil
}

